nltl:I2_004Shape
    a sh:NodeShape ;
    sh:targetClass nltl:ship ;
    sh:description "Activated representation of I2-004, UR I2 Structural Requirements for Polar Class Ships, clause I2.1.2.2. The admitted population is the caller-declared complete synthetic population of nltl:ship records. The source states that UR I2 applies to Polar Class ships according to UR I1; that applicability is retained as source text and is not independently re-certified by this shape." ;
    sh:description "Source evidence: data/requirements/IACS_I2_full.txt; document SHA-256 7ad8d57459782b70809da479380584a57cf259c66d9ff286811c0248b02732d2; retained selection offsets 0-1304; selection SHA-256 c6e77eb821ae603a13c191d7eb5073821d353775215f91d431bb454faf9207cb. Requirement text: I2.1.2.2 The ship displacement DUI is the displacement, in kt, of the ship corresponding to the upper ice waterline (UIWL). Where multiple waterlines are used for determining the UIWL, the displacement is to be determined from the waterline corresponding to the greatest displacement." ;
    sh:description "Source-context uncertainty retained: the source references UR I1 without a locally represented applicability binding. The caller supplied UR I1 Rev.2 (April 2016) as experimental contextual scope evidence only; no additional applicability selector is inferred." ;
    sh:node [
        sh:class nltl:ship ;
        sh:message "The focus node must remain within the caller-admitted ship population."
    ] ;
    sh:property [
        sh:path nltl:upperIceWaterlineDisplacement ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:node nltl:I2_004_QuantityShape ;
        sh:message "Each admitted ship must have exactly one upper ice waterline displacement quantity."
    ] ;
    sh:property [
        sh:path nltl:hasUpperIceWaterlineCase ;
        sh:minCount 1 ;
        sh:node nltl:I2_004_CaseShape ;
        sh:message "Each admitted ship must have at least one upper ice waterline case."
    ] ;
    sh:sparql [
        a sh:SPARQLConstraint ;
        sh:message "The ship displacement must correspond to a waterline case having the greatest displacement among the waterline cases used to determine the UIWL." ;
        sh:select """
            SELECT DISTINCT $this
            WHERE {
                $this nltl:upperIceWaterlineDisplacement ?duiQuantity .
                ?duiQuantity qudt:numericValue ?duiValue .

                FILTER (
                    NOT EXISTS {
                        $this nltl:hasUpperIceWaterlineCase ?case .
                        ?case nltl:waterlineCaseDisplacement ?caseQuantity .
                        ?caseQuantity qudt:numericValue ?caseValue .
                        FILTER ( ?caseValue = ?duiValue )
                    }
                    ||
                    EXISTS {
                        $this nltl:hasUpperIceWaterlineCase ?greaterCase .
                        ?greaterCase nltl:waterlineCaseDisplacement ?greaterQuantity .
                        ?greaterQuantity qudt:numericValue ?greaterValue .
                        FILTER ( ?greaterValue > ?duiValue )
                    }
                )
            }
        """ ;
    ] .

nltl:I2_004_CaseShape
    a sh:NodeShape ;
    sh:class nltl:upperIceWaterlineCase ;
    sh:property [
        sh:path nltl:waterlineCaseDisplacement ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:node nltl:I2_004_QuantityShape ;
        sh:message "Each upper ice waterline case must have exactly one waterline case displacement quantity."
    ] ;
    sh:message "A linked upper ice waterline case must be an nltl:upperIceWaterlineCase and must carry its case displacement."
    .

nltl:I2_004_QuantityShape
    a sh:NodeShape ;
    sh:class qudt:QuantityValue ;
    sh:property [
        sh:path qudt:numericValue ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:datatype xsd:decimal ;
        sh:message "A displacement quantity must have exactly one xsd:decimal qudt:numericValue."
    ] ;
    sh:property [
        sh:path qudt:unit ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:hasValue unit:KiloTON_Metric ;
        sh:message "A displacement quantity must have exactly one unit, qudt:unit KiloTON_Metric."
    ] ;
    sh:message "Displacement quantities use the declared QUDT quantity representation with qudt:numericValue as xsd:decimal and qudt:unit as an IRI."
    .
